/** Transport contracts shared by list endpoints and their UI adapters. */
export interface PageResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

/** Stable list state shared by local and URL-backed resource views. */
export interface ListRequest {
  page: number;
  pageSize: number;
  search: string;
  /** Per-column list filters generated by the shared table search form. */
  filters?: Record<string, string>;
  filterModes?: Record<string, "contains" | "exact" | "range">;
}

export const DEFAULT_TABLE_PAGE_SIZE = 10;
export const TABLE_PAGE_SIZE_OPTIONS = [10, 20, 50, 100] as const;

/** Single source of truth for local and URL-backed list defaults. */
export function createListRequest(overrides: Partial<ListRequest> = {}): ListRequest {
  return { page: 1, pageSize: DEFAULT_TABLE_PAGE_SIZE, search: "", filters: {}, filterModes: {}, ...overrides };
}

/** Build the common URL shape used by paginated endpoints. */
export function listRequestParams(
  request: ListRequest,
  extra: Record<string, string | number | boolean | null | undefined> = {},
): URLSearchParams {
  const params = new URLSearchParams({
    page: String(request.page),
    pageSize: String(request.pageSize),
    search: request.search,
  });
  for (const [key, value] of Object.entries(extra)) {
    if (value !== null && value !== undefined) params.set(key, String(value));
  }
  for (const [key, value] of Object.entries(request.filters ?? {})) {
    if (value !== "") params.set(`filter.${key}`, value);
  }
  for (const [key, value] of Object.entries(request.filterModes ?? {})) {
    params.set(`filterMode.${key}`, value);
  }
  return params;
}

/** Apply list-form filters to fully loaded client-side catalogues and trees. */
export function matchesListFilters(
  row: Record<string, unknown>,
  filters: Record<string, string> = {},
  modes: Record<string, "contains" | "exact" | "range"> = {},
): boolean {
  const stringify = (value: unknown) => value && typeof value === "object" ? JSON.stringify(value) : String(value ?? "");
  for (const [field, mode] of Object.entries(modes)) {
    const expected = filters[field];
    const actual = row[field];
    if (mode === "range") {
      const actualTime = new Date(stringify(actual)).getTime();
      const from = filters[`${field}.from`];
      const to = filters[`${field}.to`];
      if (Number.isNaN(actualTime) || (from && actualTime < new Date(from).getTime()) || (to && actualTime > new Date(to).getTime())) return false;
    } else if (expected !== undefined && mode === "exact") {
      if (stringify(actual).toLocaleLowerCase() !== expected.toLocaleLowerCase()) return false;
    } else if (expected !== undefined && !stringify(actual).toLocaleLowerCase().includes(expected.toLocaleLowerCase())) return false;
  }
  return true;
}
